/// Card-event payload for `after_card_played` / `after_card_exhausted`.
///
/// Carries the played card's [`CardTags`](crate::cards::CardTags) so
/// listeners (`LostWisp`, `FakeStrikeDummy`) can branch on tag without
/// re-indexing the card store. Tag plumbing landed with bead
/// `sts2-rs-3f8`; the per-instance enchantment / upgrade state lives on
/// the `Card` POD in `crate::cards` and is reached via `card_uid`.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct CardEventCtx {
    /// Stable identity of the played card.
    pub card_id: crate::cards::CardId,
    /// Per-instance handle into `CardStore` (`None` if the card has no
    /// store-backed instance yet — e.g. an off-deck synthesized card).
    pub card_uid: Option<crate::CardUid>,
    /// Target the card was played at, if any.
    pub target: Option<crate::CreatureUid>,
    /// Tag bitset of the played card (mirrors `Card.tags`). Bead
    /// `sts2-rs-3f8` plumbed this; listeners use it for `CardTag::Strike`
    /// queries without an arena round-trip.
    pub card_tags: crate::cards::CardTags,
    /// Energy ACTUALLY paid for this play (C# `cardPlay.Resources.EnergyValue`):
    /// the effective post-modifier cost for a normal card, or all drained energy
    /// for an X-cost card. Populated only at the `before_card_played` dispatch
    /// site in `combat_loop::play_card` (where the spend is known); all other
    /// construction sites (exhaust events, after-played, off-deck synthesized
    /// cards) set `0`. `IntimidatingHelmet` gates on this to mirror C#
    /// `BeforeCardPlayed`'s `EnergyValue >= 2` check, which the printed-`cost`
    /// gate diverged from for X-cost and cost-modified plays.
    pub energy_spent: i32,
}

