/// Dispatch `before_hand_draw` to every registered listener.
pub fn dispatch_before_hand_draw(state: &mut CombatState) -> EffectResult {
    if is_empty_before_hand_draw() {
        return EffectResult::NotImplemented;
    }
    walk_guarded_event(
        registry_before_hand_draw(),
        GuardedChannel::BeforeHandDraw,
        state,
        |f, state| f(state),
    )
}

/// Walk `before_hand_draw` in player EQUIP order (`state.relics` order, C#
/// `CombatState.IterateHookListeners` inside `Hook.BeforeHandDraw`),
/// starting at equip index `from`, and SUSPEND right after a listener opens a
/// card choice. Returns the equip index to resume from once that choice
/// resolves, or `None` when the walk completed.
///
/// C# awaits each listener: Toolbox (`Toolbox.cs`) awaits its
/// `FromChooseACardScreen` before the next relic's `BeforeHandDraw` runs, so
/// a relic equipped after it (NinjaScroll's Shivs, FuneraryMask's Souls,
/// ToastyMittens, …) must act only after the pick lands in hand.
pub fn dispatch_before_hand_draw_from(state: &mut CombatState, from: u8) -> Option<u8> {
    if is_empty_before_hand_draw() {
        return None;
    }
    let owned = collect_equip_order_listeners(registry_before_hand_draw(), state);
    for (idx, _, f) in owned {
        if idx < usize::from(from) {
            continue;
        }
        let had_choice = state.pending_choice.is_some();
        let _ = f(state);
        if !had_choice && state.pending_choice.is_some() {
            return Some(u8::try_from(idx.saturating_add(1)).unwrap_or(u8::MAX));
        }
        if state.is_over {
            break;
        }
    }
    None
}

/// Dispatch `after_side_turn_start` to every OWNED relic's listener, in
/// player EQUIP order (`state.relics` order).
pub fn dispatch_after_side_turn_start(state: &mut CombatState, side: Side) -> EffectResult {
    if is_empty_after_side_turn_start() {
        return EffectResult::NotImplemented;
    }
    // C#-faithful firing order: relic hooks fire in EQUIP order
    // (`player.Relics` via `CombatState.IterateHookListeners`), NOT RelicId
    // order. This is observable when two equipped relics share this hook and
    // order matters: FencingManual's forge (`RelicId` 61) would otherwise fire
    // before BoneTea's hand-upgrade (`RelicId` 361) regardless of acquisition
    // order, upgrading the freshly forged SovereignBlade (sweep seed 140: the
    // blade costs 2 in C#, was upgraded to 1 here because BoneTea was equipped
    // FIRST and so fires first in C#).
    //
    // Rather than snapshot ALL globally-registered listeners into a heap `Vec`
    // and re-sort that whole list by equip index every call (recomputing a
    // `state.relics.position` scan inside the `sort_by_key` comparator, which
    // re-evaluates the key O(n·log n) times), collect ONLY the owned relics'
    // handlers — each tagged with its equip index — under a single read lock,
    // then sort that small owned set by the precomputed index. Listeners for
    // unequipped relics are never collected; they previously self-no-op'd on
    // their `player_owns_relic` guard, so omitting them is bit-identical. See
    // `dispatch_before_side_turn_start` (m4jaj) for the owned-iteration
    // precedent. Bead `sts2-rs-b8z17`. M01: that collect-and-sort is now done
    // once per combat (`RelicPlan`); the walk below is the fallback.
    // Same empty-relics registry-walk skip as `collect_owned_listeners`.
    if state.relics.is_empty() {
        return EffectResult::NotImplemented;
    }
    let mut any_resolved = false;
    if let Some((frozen, order)) = planned_equip_order(
        registry_after_side_turn_start(),
        state,
        READY_AFTER_SIDE_TURN_START,
        |p| &p.after_side_turn_start,
    ) {
        for slot in order.slots() {
            if (frozen[usize::from(slot.entry)].1)(state, side) == EffectResult::Resolved {
                any_resolved = true;
            }
        }
    } else {
        for (_, _, f) in collect_equip_order_listeners(registry_after_side_turn_start(), state) {
            if f(state, side) == EffectResult::Resolved {
                any_resolved = true;
            }
        }
    }
    if any_resolved {
        EffectResult::Resolved
    } else {
        EffectResult::NotImplemented
    }
}

/// Dispatch `after_player_turn_start` to every registered listener, from the
/// top of the equip order.
///
/// Fired from the `combat_loop` player-turn-start `AfterPlayerTurnStart`
/// cluster (before Step 9's `after_side_turn_start` / Rampart grant), mirroring
/// C# `SetupPlayerTurn`'s `AfterPlayerTurnStart` preceding the outer-loop
/// `Hook.AfterSideTurnStart`. Bead `sts2-rs-axdgh`.
///
/// Returns `Some(next_equip_idx)` when a listener SUSPENDED the walk by opening
/// a `pending_choice` (GamblingChip's round-1 mulligan — C# `await`s the
/// `CardSelectCmd` inside `Hook.AfterPlayerTurnStart`, so every later listener
/// waits for the pick); `None` when the whole walk ran.
pub fn dispatch_after_player_turn_start(state: &mut CombatState) -> Option<u8> {
    dispatch_after_player_turn_start_from(state, 0)
}

/// [`dispatch_after_player_turn_start`], resuming at equip index `from`.
///
/// Listener order is the player's RELIC EQUIP order, not the `RelicId`
/// discriminant order the registry `BTreeMap` yields: C#
/// `Hook.AfterPlayerTurnStart` walks `IterateCombatHookListeners`, which emits
/// the owner's relics in inventory order (same rationale as
/// `dispatch_before_side_turn_start`, bead `sts2-rs-m4jaj`). That order is what
/// decides which relics fire BEFORE GamblingChip's mulligan screen and which
/// wait for it (seed 1004: `[… GAMBLING_CHIP, …, MERCURY_HOURGLASS, …]` — the
/// hourglass's 3 damage lands only after the pick).
pub fn dispatch_after_player_turn_start_from(state: &mut CombatState, from: u8) -> Option<u8> {
    if is_empty_after_player_turn_start() {
        return None;
    }
    // No-relics early-out (perf-gates sweep 2026-07-04): the owned-collect
    // below can only yield handlers for relics in `state.relics`, so an empty
    // relic list makes the walk provably empty — skip the registry access.
    if state.relics.is_empty() {
        return None;
    }
    // M01: the equip-order list comes from the per-combat `RelicPlan` when it
    // covers this channel; positions are raw `state.relics` indices either way.
    if let Some((frozen, order)) = planned_equip_order(
        registry_after_player_turn_start(),
        state,
        READY_AFTER_PLAYER_TURN_START,
        |p| &p.after_player_turn_start,
    ) {
        return run_after_player_turn_start(
            state,
            from,
            order
                .slots()
                .iter()
                .map(|s| (usize::from(s.equip_idx), frozen[usize::from(s.entry)].1)),
        );
    }
    run_after_player_turn_start(
        state,
        from,
        collect_equip_order_listeners(registry_after_player_turn_start(), state)
            .into_iter()
            .map(|(idx, _, f)| (idx, f)),
    )
}

/// The `after_player_turn_start` walk over an equip-ordered `(equip_idx,
/// handler)` list, resuming at `from` and suspending when a listener opens a
/// choice (see [`dispatch_after_player_turn_start_from`]).
fn run_after_player_turn_start(
    state: &mut CombatState,
    from: u8,
    owned: impl Iterator<Item = (usize, AfterPlayerTurnStartFn)>,
) -> Option<u8> {
    for (idx, f) in owned {
        if idx < usize::from(from) {
            continue;
        }
        // Only a choice THIS listener opened suspends the walk; one already
        // open from an earlier surface does not.
        let had_choice = state.pending_choice.is_some();
        let _ = f(state);
        if !had_choice && state.pending_choice.is_some() {
            // The listener opened a blocking card screen. C# awaits it inside
            // the hook walk, so the remaining listeners must not run until it
            // resolves — hand the caller the index to resume from.
            return Some(u8::try_from(idx.saturating_add(1)).unwrap_or(u8::MAX));
        }
    }
    None
}

/// Dispatch `before_side_turn_start` to every registered listener.
pub fn dispatch_before_side_turn_start(state: &mut CombatState, side: Side) -> EffectResult {
    if is_empty_before_side_turn_start() {
        return EffectResult::NotImplemented;
    }
    // No-relics early-out (perf-gates sweep 2026-07-04): the obtain-order
    // walk below iterates `state.relics`, so an empty relic list fires
    // nothing — skip the full `listeners_*()` heap snapshot entirely.
    if state.relics.is_empty() {
        return EffectResult::NotImplemented;
    }
    // Bead `sts2-rs-m4jaj`: fire combat-start relic hooks in the player's
    // OBTAIN order (the order relics sit in `state.relics`), NOT the
    // RelicId-discriminant order the `BTreeMap` registry yields. Order is
    // observable when an enemy has `ArtifactPower` (it negates the FIRST
    // debuff applied, so only the LAST-applied survives): RedMask (Weak 1)
    // + TwistedFunnel (Poison 4) against a CONSTRUCT_MENAGERIE Artifact
    // construct leave only the relic that fires LAST. C# applies in obtain
    // order (e.g. [TwistedFunnel, …, RedMask] → Poison eaten, Weak lands);
    // the discriminant order fired RedMask first (Weak eaten, Poison lands),
    // inverting the surviving debuff (parity seed 1686). Match by python
    // name (RelicKind::python_name == RelicId::to_python_name, test-pinned)
    // so no RelicKind→RelicId bridge is needed.
    // Melted relics (ToyBox wax) are filtered out of the C# listener list at
    // `CombatState.cs:130-137`, so they never reach this obtain-order walk.
    //
    // M01: that per-relic name search over the whole registry (9% of boss
    // instructions) is resolved once per combat into the `RelicPlan`'s
    // obtain-order list; the walk below is the fallback.
    let mut any_resolved = false;
    let relic_plan = state.relics.plan();
    let planned = if relic_plan.ready & READY_BEFORE_SIDE_TURN_START == 0 {
        None
    } else {
        registry_before_side_turn_start()
            .frozen_view()
            .map(|frozen| (frozen, relic_plan.before_side_turn_start))
    };
    if let Some((frozen, order)) = planned {
        #[cfg(debug_assertions)]
        shadow_obtain_order(state, frozen, &order);
        for &entry in order.entries() {
            let had_choice = state.pending_choice.is_some();
            if (frozen[usize::from(entry)].1)(state, side) == EffectResult::Resolved {
                any_resolved = true;
            }
            // `Hook.BeforeSideTurnStart` (Hook.cs:1288-1302 v0.107.1) goes on
            // past a paused listener.
            crate::park_listener_choice(state, had_choice);
        }
    } else {
        let listeners = listeners_before_side_turn_start();
        let mut owned: smallvec::SmallVec<[BeforeSideTurnStartFn; 8]> = smallvec::SmallVec::new();
        for_each_obtain_order_listener(&listeners, &state.relics, |_, f| owned.push(f));
        for f in owned {
            let had_choice = state.pending_choice.is_some();
            if f(state, side) == EffectResult::Resolved {
                any_resolved = true;
            }
            crate::park_listener_choice(state, had_choice);
        }
    }
    if any_resolved {
        EffectResult::Resolved
    } else {
        EffectResult::NotImplemented
    }
}

/// Dispatch `after_card_played` to every registered listener.
pub fn dispatch_after_card_played(state: &mut CombatState, ctx: &CardEventCtx) -> EffectResult {
    if is_empty_after_card_played() {
        return EffectResult::NotImplemented;
    }
    // No-relics early-out: `collect_owned_listeners` is provably empty.
    // Fires per card play — the skip avoids the registry access on the
    // relic-less MCTS rollout hot path.
    if state.relics.is_empty() {
        return EffectResult::NotImplemented;
    }
    // EQUIP order, not `RelicId` order: C# `Hook.AfterCardPlayed` walks
    // `CombatState.IterateHookListeners`, which lists each player's relics in
    // `player.Relics` order (CombatState.cs:118-140, both builds). Iron Club
    // obtained before Mummified Hand draws its card before Mummified Hand
    // picks from the hand (Ironclad 4029 act 3), whatever the `RelicId`s.
    let mut any_resolved = false;
    if let Some((frozen, order)) = planned_equip_order(
        registry_after_card_played(),
        state,
        READY_AFTER_CARD_PLAYED_ORDER,
        |p| &p.after_card_played,
    ) {
        for slot in order.slots() {
            if (frozen[usize::from(slot.entry)].1)(state, ctx) == EffectResult::Resolved {
                any_resolved = true;
            }
        }
    } else {
        for (_, _, f) in collect_equip_order_listeners(registry_after_card_played(), state) {
            if f(state, ctx) == EffectResult::Resolved {
                any_resolved = true;
            }
        }
    }
    if any_resolved {
        EffectResult::Resolved
    } else {
        EffectResult::NotImplemented
    }
}

/// [`dispatch_after_card_played`] from the `from`-th listener in equip order,
/// stopping after the first listener for which `stop` holds. Returns where
/// to go on (the next listener's position), or `None` once the walk is done.
///
/// C# `Hook.AfterCardPlayed` awaits each listener with the play's own choice
/// context (Hook.cs:422-430, both builds), so a listener whose draw opens a
/// pick (Iron Club's draw reshuffling into Stratagem's grid) holds the later
/// relics until it resolves.
pub fn dispatch_after_card_played_from(
    state: &mut CombatState,
    ctx: &CardEventCtx,
    from: usize,
    stop: impl Fn(&CombatState) -> bool,
) -> Option<usize> {
    if is_empty_after_card_played() || state.relics.is_empty() {
        return None;
    }
    let calls: smallvec::SmallVec<[AfterCardPlayedFn; 8]> = if let Some((frozen, order)) =
        planned_equip_order(
            registry_after_card_played(),
            state,
            READY_AFTER_CARD_PLAYED_ORDER,
            |p| &p.after_card_played,
        ) {
        order
            .slots()
            .iter()
            .map(|slot| frozen[usize::from(slot.entry)].1)
            .collect()
    } else {
        collect_equip_order_listeners(registry_after_card_played(), state)
            .into_iter()
            .map(|(_, _, f)| f)
            .collect()
    };
    for (i, f) in calls.into_iter().enumerate().skip(from) {
        let _ = f(state, ctx);
        if stop(state) {
            return Some(i + 1);
        }
    }
    None
}

/// Dispatch `before_card_played` to every registered listener. Bead
/// `sts2-rs-ff3hr`: relic-side `&mut state` channel (IntimidatingHelmet).
/// Fired from `combat_loop::play_card` after the energy spend and the
/// Hand→Play move.
pub fn dispatch_before_card_played(state: &mut CombatState, ctx: &CardEventCtx) -> EffectResult {
    if is_empty_before_card_played() {
        return EffectResult::NotImplemented;
    }
    // No-relics early-out: `collect_owned_listeners` is provably empty.
    // Fires per card play.
    if state.relics.is_empty() {
        return EffectResult::NotImplemented;
    }
    let mut any_resolved = false;
    for f in owned_listeners(
        registry_before_card_played(),
        OwnedChannel::BeforeCardPlayed,
        state,
    ) {
        if f(state, ctx) == EffectResult::Resolved {
            any_resolved = true;
        }
    }
    if any_resolved {
        EffectResult::Resolved
    } else {
        EffectResult::NotImplemented
    }
}

/// Dispatch `after_card_exhausted` to every registered listener, in player
/// EQUIP order (`state.relics` order).
///
/// C# `Hook.AfterCardExhausted` walks `IterateHookListeners`, which yields the
/// player's relics in the order they were obtained, so e.g. BurningSticks and
/// JossPaper react to one exhaust in equip order (random-loadout v0.107.1 seed
/// 1176). The handler set is exactly the guarded walk's (the plan's call bits,
/// or every handler without a plan); only the order changes: handlers of an
/// owned relic sort by its first non-melted equip slot, the rest (unowned,
/// self-no-op) keep `RelicId` order after them.
pub fn dispatch_after_card_exhausted(state: &mut CombatState, ctx: &CardEventCtx) -> EffectResult {
    if is_empty_after_card_exhausted() {
        return EffectResult::NotImplemented;
    }
    let registry = registry_after_card_exhausted();
    let equip_slot = |state: &CombatState, id: RelicId| {
        id.to_relic_kind()
            .and_then(|k| {
                state
                    .relics
                    .iter()
                    .position(|r| !r.is_melted && r.kind == k)
            })
            .unwrap_or(usize::MAX)
    };
    let mut calls: smallvec::SmallVec<[(usize, AfterCardExhaustedFn); 8]> =
        smallvec::SmallVec::new();
    if let Some((frozen, mut bits)) =
        guarded_plan(registry, GuardedChannel::AfterCardExhausted, state)
    {
        while bits != 0 {
            let i = bits.trailing_zeros() as usize;
            bits &= bits - 1;
            calls.push((equip_slot(state, frozen[i].0), frozen[i].1));
        }
    } else {
        for (id, f) in registry.listeners() {
            calls.push((equip_slot(state, id), f));
        }
    }
    calls.sort_by_key(|(slot, _)| *slot);
    let mut any_resolved = false;
    for (_, f) in calls {
        if f(state, ctx) == EffectResult::Resolved {
            any_resolved = true;
        }
    }
    if any_resolved {
        EffectResult::Resolved
    } else {
        EffectResult::NotImplemented
    }
}

