/// Dispatch `modify_damage_additive` and accumulate the deltas from
/// every registered listener (additive — matches Python convention in
/// `sts2-rl-agent@01c094d:sts2_env/relics/base.py`: each handler
/// returns an `int` delta and the dispatcher sums them).
pub fn dispatch_modify_damage_additive(state: &CombatState, ctx: &ModifyDamageCtx) -> i32 {
    if is_empty_modify_damage_additive() {
        return 0;
    }
    // No-relics early-out: `collect_owned_listeners` is provably empty, so
    // the fold is the additive identity. Fires per damage calc — hot on the
    // relic-less MCTS rollout path.
    if state.relics.is_empty() {
        return 0;
    }
    let mut total: i32 = 0;
    for f in owned_listeners(
        registry_modify_damage_additive(),
        OwnedChannel::ModifyDamageAdditive,
        state,
    ) {
        total = total.saturating_add(f(state, ctx));
    }
    total
}

/// Dispatch `modify_block_multiplicative` and compose the rational
/// multipliers from every registered relic handler. Bead
/// `sts2-rs-y81a` (6z05.2). Mirrors the power-side composition
/// performed by [`crate::hooks::dispatch_modify_block_multiplicative`]:
/// the result is the product (via `DamageMul::compose`) of every
/// registered handler's contribution.
///
/// Returns [`crate::hooks::DamageMul::ONE`] when no handlers are
/// registered, matching the identity-multiplier convention used
/// elsewhere in the block pipeline.
pub fn dispatch_modify_block_multiplicative(
    state: &CombatState,
    ctx: &crate::hooks::BlockCtx,
) -> crate::hooks::DamageMul {
    if is_empty_modify_block_multiplicative() {
        return crate::hooks::DamageMul::ONE;
    }
    // No-relics early-out + owned-collect (perf-gates sweep 2026-07-04):
    // converted from the full `listeners_*()` heap snapshot to the
    // `collect_owned_listeners` pattern (same `RelicId` firing order).
    // Bit-identical: both production registrants on this channel (Vambrace's
    // first-card doubler, `vambrace.rs::on_modify_block_multiplicative_vambrace`,
    // and PaelsLegion's armed doubler,
    // `shop_event.rs::listener_paels_legion_modify_block`) return
    // `DamageMul::ONE` when their relic is absent from `state.relics` —
    // verified per the `collect_owned_listeners` contract before conversion.
    // Fires per block gain (inside `hooks::modify_block`) — hot path.
    if state.relics.is_empty() {
        return crate::hooks::DamageMul::ONE;
    }
    let mut acc = crate::hooks::DamageMul::ONE;
    for f in owned_listeners(
        registry_modify_block_multiplicative(),
        OwnedChannel::ModifyBlockMultiplicative,
        state,
    ) {
        acc = acc.compose(f(state, ctx));
    }
    acc
}

