/// damage-given dispatch ([`crate::damage::apply_damage_full`]), gated on the
/// `just_died` HP-cross-to-zero transition
/// (so it fires exactly once per death — a later hit on a 0-HP corpse has
/// `pre_hp == 0`). Death paths that route through `apply_damage` (attacks,
/// Poison, Thorns, Constrict self-damage, Doom's self-lethal tick) all reach
/// this chokepoint, matching the power-side [`crate::hooks::dispatch_after_death`].
///
/// Returns `Resolved` if any listener returned `Resolved`, otherwise
/// `NotImplemented`. Empty-bus early-out preserves the no-listener fast path.
pub fn dispatch_after_death(
    state: &mut CombatState,
    ctx: &crate::hooks::AfterDeathCtx,
) -> EffectResult {
    if is_empty_after_death() {
        return EffectResult::NotImplemented;
    }
    walk_guarded_event(
        registry_after_death(),
        GuardedChannel::AfterDeath,
        state,
        |f, state| {
            // `Hook.AfterDeath` (Hook.cs:594-606) goes on past a paused listener.
            let had_choice = state.pending_choice.is_some();
            let result = f(state, ctx);
            crate::park_listener_choice(state, had_choice);
            result
        },
    )
}

/// Dispatch `modify_hp_lost` as a left-to-right fold over the owned
/// relics' listeners — each handler receives the current amount and
/// returns the new amount.
///
/// The fold runs in relic OBTAIN order (`state.relics` order): C#
/// `Hook.ModifyHpLost` (`Hook.cs:1870-1905`, both builds) folds over
/// `IterateHookListeners`, and Tungsten Rod's `-1` does not commute with
/// Beating Remnant's per-turn cap. The Boot (`AfterOstyLate`) only acts on
/// hits against an enemy, which the other two never touch, so the one
/// shared fold stays exact. With at most one owned listener the order is
/// moot and the plan path is kept.
pub fn dispatch_modify_hp_lost(
    state: &CombatState,
    ctx: &ModifyHpLostCtx,
    base_amount: i32,
) -> i32 {
    if is_empty_modify_hp_lost() {
        return base_amount;
    }
    // No-relics early-out: `collect_owned_listeners` is provably empty, so
    // the fold is the identity on `base_amount`. Fires per HP loss — hot on
    // the relic-less MCTS rollout path.
    if state.relics.is_empty() {
        return base_amount;
    }
    let mut current = base_amount;
    let mut owned = owned_listeners(registry_modify_hp_lost(), OwnedChannel::ModifyHpLost, state);
    let Some(first) = owned.next() else {
        return current;
    };
    if owned.next().is_none() {
        return first(state, ctx, current);
    }
    for (_, _, f) in collect_equip_order_listeners(registry_modify_hp_lost(), state) {
        current = f(state, ctx, current);
    }
    current
}

/// Dispatch `modify_hand_draw` as a left-to-right fold. Mirrors Python
