/// Dispatch the relic-side `modify_card_play_count` channel as a
/// saturating sum of per-listener deltas. Mirrors Python's
/// `relic.modify_card_play_count(owner, count, card)` walk (each Python
/// listener returns the *new total*; the Rust convention returns the
/// *delta* added to the base of 1 by the caller, matching how
/// [`crate::hooks::dispatch_modify_card_play_count`] folds power-side
/// contributions). Listeners may mutate `state` (e.g. ThrowingAxe sets
/// its once-per-combat latch on the relic's `counter` field). Empty-bus
/// early-out returns `0`. Bead `sts2-rs-70anj.3.3`.
pub fn dispatch_relic_modify_card_play_count(
    state: &mut CombatState,
    ctx: &crate::hooks::CardPlayCountCtx,
) -> i32 {
    if is_empty_relic_modify_card_play_count() {
        return 0;
    }
    walk_guarded_mut(
        registry_relic_modify_card_play_count(),
        GuardedChannel::RelicModifyCardPlayCount,
        state,
        0i32,
        |f, state| f(state, ctx),
        i32::saturating_add,
    )
}

/// Dispatch `modify_power_amount_given` as a left-to-right fold over
/// registered relic listeners — each handler receives `ctx.amount`
/// (the running amount) and returns the new amount. Bead
/// `sts2-rs-47jv`. Walks listeners in deterministic `RelicId` order so
/// the result is reproducible. Empty-bus early-out returns
/// `ctx.amount` unchanged.
pub fn dispatch_modify_power_amount_given(
    state: &CombatState,
    ctx: &crate::hooks::PowerAmountCtx,
) -> i32 {
    if is_empty_modify_power_amount_given() {
        return ctx.amount;
    }
    walk_guarded(
        registry_modify_power_amount_given(),
        GuardedChannel::ModifyPowerAmountGiven,
        state,
        ctx.amount,
        |f, current| {
            f(
                state,
                &crate::hooks::PowerAmountCtx {
                    amount: current,
                    ..*ctx
                },
            )
        },
    )
}

