/// Dispatch `modify_rewards` — every listener is a mutate-in-place
/// handler over the reward queue. Mirrors Python
/// `Relic.modify_rewards(owner, rewards, room, run_state) -> list[Reward]`,
/// but the Rust convention is `&mut Vec<Reward>` so listeners can
/// `push` / `retain` / `clear` without copying. Walks listeners in
/// deterministic `RelicId` order.
pub fn dispatch_modify_rewards(state: &CombatState, rewards: &mut Vec<Reward>) {
    if is_empty_modify_rewards() {
        return;
    }
    let listeners = equip_ordered_snapshot(state, listeners_modify_rewards());
    for (_id, f) in listeners {
        f(state, rewards);
    }
}

